class TableMatrixToJSON(Component):
    display_name = "Table Markdown/Matrix → JSON (Profiler + Clustering + Structured Export)"
    description = (
        "Parses table text (pipe-markdown from the markdown pipeline, or a "
        "legacy JSON matrix) into a matrix, then runs structural profiling, "
        "clustering and structured JSON export."
    )

    inputs = [
        DataFrameInput(
            name="dataframe",
            display_name="Input DataFrame with table text"
        ),

        BoolInput(name="export_json", display_name="Export Debug JSON", value=False, info="Debug only: write this component's intermediate output as a JSON file under /data/uploads/misc. Off in production.")
    ]

    outputs = [
        Output(
            name="result",
            display_name="DataFrame with JSON Tables",
            method="process",
            type=DataFrame,
        )
    ]

    TABLE_SCHEMA = {
        "type": "array",
        "items": {"type": "array"}
    }

    # cell that is only a markdown alignment separator: ---  :---  ---:  :---:
    _MD_SEP_CELL = re.compile(r"^\s*:?-{2,}:?\s*$")

    # =========================================================
    # TABLE TEXT -> MATRIX  (markdown pipe table OR legacy JSON)
    # =========================================================

    def markdown_to_matrix(self, text: str):
        """Parse a pipe-markdown table into a list-of-lists matrix.

        - only lines starting with '|' are table rows
        - alignment separator rows (| --- | :---: |) are skipped -- also
          mid-text, because the splitter merges page-broken fragments that
          each carry their own header separator
        - escaped pipes (\|) inside cells are preserved
        - ragged rows are returned as-is; the analyzer pads with None
        """
        rows = []
        for line in text.splitlines():
            s = line.strip()
            if not s.startswith("|"):
                continue
            s = s.replace("\\|", "\x00")          # protect escaped pipes
            cells = s.split("|")
            if cells and cells[0].strip() == "":
                cells = cells[1:]                   # boundary artifact only
            if cells and cells[-1].strip() == "":
                cells = cells[:-1]
            cells = [c.replace("\x00", "|").strip() for c in cells]
            if not cells:
                continue
            if any(self._MD_SEP_CELL.match(c) for c in cells) and all(
                self._MD_SEP_CELL.match(c) or c == "" for c in cells
            ):
                continue                            # alignment row, not data
            rows.append(cells)
        return rows or None

    def parse_table_text(self, text):
        """Return a matrix from legacy JSON ([[...]]) or pipe-markdown."""
        if not isinstance(text, str) or not text.strip():
            return None
        s = text.strip()
        if s.startswith("["):                       # legacy JSON matrix
            try:
                m = json.loads(s)
                return m if isinstance(m, list) else None
            except Exception:
                return None
        if "|" in s:
            return self.markdown_to_matrix(s)
        return None

    # =========================================================
    # JSON SAFE CONVERTER (UNCHANGED)
    # =========================================================

    def json_safe(self, value):

        if pd.isna(value):
            return None

        if isinstance(value, (np.integer,)):
            return int(value)

        if isinstance(value, (np.floating,)):
            return float(value)

        if isinstance(value, dict):
            return {k: self.json_safe(v) for k, v in value.items()}

        if isinstance(value, list):
            return [self.json_safe(v) for v in value]

        return value

    # =========================================================
    # MAIN PROCESS (UNCHANGED)
    # =========================================================

    def process(self) -> DataFrame:

        df = self.dataframe

        if not isinstance(df, pd.DataFrame):
            return DataFrame(pd.DataFrame())

        if df.empty:
            return DataFrame(df)

        df = df.copy()

        export_json_enabled = bool(self.export_json)

        # ---------------------------------------------------------
        # MATRIX ANALYZER (UNCHANGED)
        # ---------------------------------------------------------

        def analyze_matrix(matrix_text: str):

            matrix = self.parse_table_text(matrix_text)
            if matrix is None:
                return (None, False, None, None, None, None, None,
                        None, None, None, None)

            try:
                validate(instance=matrix, schema=self.TABLE_SCHEMA)
                json_valid = True
            except ValidationError:
                json_valid = False

            if not isinstance(matrix, list) or not matrix:
                return (None, False, None, None, None, None, None,
                        None, None, None, None)

            rows = len(matrix)
            cols = max(len(r) for r in matrix if isinstance(r, list))

            null_count = 0
            empty_count = 0
            total_cells = 0
            numeric_cells = 0
            cell_lengths = []

            col_stats = [
                {"null": 0, "empty": 0, "numeric": 0, "lengths": []}
                for _ in range(cols)
            ]

            row_profile = {}
            structured_json = {}

            # Header detection: use row 0 as column names when it looks like a
            # header (>=2 non-empty, non-numeric cells). Then data cells are keyed
            # by their column HEADER instead of column_NN, so each cell is
            # self-describing ("Termín: 29. 4." not "column_02: 29. 4.").
            header = None
            if matrix and isinstance(matrix[0], list):
                h = [re.sub(r"\s+", " ", str(c).strip()) if c is not None else "" for c in matrix[0]]
                nonempty = [x for x in h if x]
                numeric_h = sum(1 for x in nonempty if re.fullmatch(r"[-+]?\d+([.,]\d+)?", x))
                if len(nonempty) >= 2 and numeric_h == 0:
                    header = h

            for r_idx, row in enumerate(matrix):

                row_key = f"row_{r_idx+1:02d}"
                row_obj = {}

                row_null = 0
                row_numeric = 0
                row_lengths = []

                for c_idx in range(cols):
                    cell = row[c_idx] if c_idx < len(row) else None
                    total_cells += 1

                    if cell is None:
                        null_count += 1
                        row_null += 1
                        col_stats[c_idx]["null"] += 1
                        continue

                    cell_str = str(cell).strip()

                    if cell_str == "":
                        empty_count += 1
                        col_stats[c_idx]["empty"] += 1
                        continue

                    length = len(cell_str)
                    cell_lengths.append(length)
                    row_lengths.append(length)
                    col_stats[c_idx]["lengths"].append(length)

                    if re.fullmatch(r"[-+]?\d+(\.\d+)?", cell_str):
                        numeric_cells += 1
                        row_numeric += 1
                        col_stats[c_idx]["numeric"] += 1

                    # #1 header-as-key + #2 drop empty (empty cells skipped above)
                    if header is not None and c_idx < len(header) and header[c_idx]:
                        cell_key = f"{row_key}_{header[c_idx]}"
                    else:
                        cell_key = f"{row_key}_column_{c_idx+1:02d}"
                    row_obj[cell_key] = cell

                row_profile[row_key] = {
                    "avg_length": mean(row_lengths) if row_lengths else 0,
                    "null_ratio": row_null / cols if cols else 0,
                    "numeric_ratio": row_numeric / cols if cols else 0,
                }

                # skip the header row itself as a data row (its cells are the keys)
                if not (header is not None and r_idx == 0):
                    structured_json[row_key] = row_obj

            column_profile = {}
            for i in range(cols):
                col_key = f"column_{i+1:02d}"
                stats = col_stats[i]

                column_profile[col_key] = {
                    "null_ratio": stats["null"] / rows if rows else 0,
                    "empty_ratio": stats["empty"] / rows if rows else 0,
                    "numeric_ratio": stats["numeric"] / rows if rows else 0,
                    "avg_length": mean(stats["lengths"]) if stats["lengths"] else 0,
                }

            empty_ratio = empty_count / total_cells if total_cells else 0
            null_ratio = null_count / total_cells if total_cells else 0
            numeric_ratio = numeric_cells / len(cell_lengths) if cell_lengths else 0

            quality_score = max(0, 100 - int(empty_ratio * 40) - int(null_ratio * 40))

            return (
                structured_json, json_valid, rows, cols,
                empty_ratio, null_ratio, numeric_ratio,
                quality_score, rows, column_profile, row_profile
            )

        (
            df["tbl_json"],
            df["tbl_json_valid"],
            df["tbl_json_rows"],
            df["tbl_json_columns"],
            df["tbl_json_empty_ratio"],
            df["tbl_json_null_ratio"],
            df["tbl_json_numeric_ratio"],
            df["tbl_json_quality_score"],
            df["tbl_json_row_count"],
            df["tbl_json_column_profile"],
            df["tbl_json_row_profile"],
        ) = zip(*[
            analyze_matrix(row["text"]) if row.get("record_type") == "table"
            else (None, False, None, None, None, None, None,
                  None, None, None, None)
            for _, row in df.iterrows()
        ])

        # ---------------------------------------------------------
        # CLUSTERING (UNCHANGED)
        # ---------------------------------------------------------

        def assign_cluster(row):

            if row.get("record_type") != "table":
                return (None, None, None, None, None)

            rows = row.get("tbl_json_rows") or 0
            cols = row.get("tbl_json_columns") or 0
            numeric_ratio = row.get("tbl_json_numeric_ratio") or 0
            density_ratio = (row.get("tbl_json_empty_ratio") or 0) + \
                            (row.get("tbl_json_null_ratio") or 0)

            size_bucket = "tiny" if rows <= 5 else "small" if rows <= 15 else "medium" if rows <= 40 else "large"
            shape_bucket = "narrow" if cols <= 3 else "regular" if cols <= 8 else "wide"
            numeric_bucket = "numeric_heavy" if numeric_ratio > 0.6 else "mixed" if numeric_ratio > 0.2 else "text_heavy"
            density_bucket = "sparse" if density_ratio > 0.5 else "dense"

            signature = f"{size_bucket}|{shape_bucket}|{numeric_bucket}|{density_bucket}"

            return size_bucket, shape_bucket, numeric_bucket, density_bucket, signature

        (
            df["tbl_size_bucket"],
            df["tbl_shape_bucket"],
            df["tbl_numeric_bucket"],
            df["tbl_density_bucket"],
            df["tbl_cluster_signature"],
        ) = zip(*df.apply(assign_cluster, axis=1))

        # ---------------------------------------------------------
        # JSON EXPORT (FIXED ONLY HERE)
        # ---------------------------------------------------------

        if export_json_enabled:

            try:

                first_row = df.iloc[0]
                timestamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")

                safe_name = re.sub(r"[^\w\-_\. ]", "_", str(first_row.get("file_name"))).replace(" ", "_")
                json_filename = f"{safe_name}_{first_row.get('file_uuid')}_table_matrix_structured_{timestamp}.json"

                debug_dir = "/data/uploads/misc"
                os.makedirs(debug_dir, exist_ok=True)

                json_path = f"{debug_dir}/{json_filename}"

                export_df = df.copy()

                # ✅ SAFE CONVERSION (REPLACED applymap)
                records = []
                for _, r in export_df.iterrows():
                    record = {}
                    for col, val in r.items():
                        record[col] = self.json_safe(val)
                    records.append(record)

                json_document = {
                    "document": {
                        "processing_uuid": first_row.get("processing_uuid"),
                        "file_uuid": first_row.get("file_uuid"),
                        "file_name": first_row.get("file_name"),
                        "created_at": timestamp,
                        "component": "TableMatrixToJSON"
                    },
                    "rows": records
                }

                with open(json_path, "w", encoding="utf-8") as f:
                    json.dump(json_document, f, ensure_ascii=False, indent=2, allow_nan=False)

                print(f"STRUCTURED TABLE JSON exported: {json_path}")

            except Exception as e:
                print(f"Structured JSON export failed: {e}")

        return DataFrame(df)

