import pandas as pd
import json
import os
from datetime import datetime


class FinalChunkFormatterVectorReady(Component):

    display_name = "Final Chunk Formatter (Vector Ready – FULL JSON)"
    description = (
        "Final formatter before vectorisation. "
        "Removes heavy/unnecessary columns and exports FULL dataframe to JSON."
    )

    inputs = [
        DataFrameInput(
            name="dataframe",
            display_name="Input DataFrame"
        ),
        BoolInput(name="export_json", display_name="Export Debug JSON", value=False, info="Debug only: write this component's intermediate output as a JSON file under /data/uploads/misc. Off in production."),
    ]

    outputs = [
        Output(
            name="result",
            display_name="Vector Ready DataFrame",
            method="process",
            type=DataFrame,
        )
    ]

    def clean_value(self, value):

        if pd.isna(value):
            return None

        if isinstance(value, (pd.Timestamp,)):
            return value.isoformat()

        if isinstance(value, (bytes, bytearray)):
            return value.decode("utf-8", errors="ignore")

        return value

    # -----------------------------------------------------
    # 🔥 NEW: EXTRACT KEYWORDS
    # -----------------------------------------------------

    def extract_keywords(self, metadata):

        if metadata is None:
            return "[]"

        # metadata can be dict or string
        if isinstance(metadata, str):
            try:
                metadata = json.loads(metadata)
            except:
                return "[]"

        if not isinstance(metadata, dict):
            return "[]"

        keywords = metadata.get("keywords", [])

        if not isinstance(keywords, list):
            return "[]"

        # ensure clean list of strings
        keywords = [str(k).strip() for k in keywords if str(k).strip()]

        return json.dumps(keywords, ensure_ascii=False)

    # -----------------------------------------------------
    # PROCESS
    # -----------------------------------------------------

    def process(self) -> DataFrame:

        try:

            df = self.dataframe

            if not isinstance(df, pd.DataFrame):
                return DataFrame(pd.DataFrame())

            if df.empty:
                return DataFrame(df)

            export_json_enabled = bool(self.export_json)

            df_out = df.copy()

            # ---------------------------------------------
            # 🔥 NEW: CREATE chunk_keywords COLUMN
            # ---------------------------------------------

            if "chunk_metadata" in df_out.columns:
                df_out["chunk_keywords"] = df_out["chunk_metadata"].apply(self.extract_keywords)
            else:
                df_out["chunk_keywords"] = "[]"

            # ---------------------------------------------
            # REMOVE UNUSED / HEAVY COLUMNS
            # ---------------------------------------------

            remove_cols = [
                "text_ingested",
                "text",
                "tbl_json",
                "tbl_json_row_profile",
                "tbl_json_column_profile",
                "model_response",
            ]

            df_out = df_out.drop(
                columns=[c for c in remove_cols if c in df_out.columns],
                errors="ignore"
            )

            # ---------------------------------------------
            # EXPORT FULL DATAFRAME TO JSON
            # ---------------------------------------------

            if export_json_enabled:

                try:

                    first_row = df_out.iloc[0]
                    timestamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")

                    file_uuid = str(first_row.get("file_uuid", "unknown"))
                    json_filename = f"{file_uuid}_final_chunks_FULL_{timestamp}.json"

                    debug_dir = "/data/uploads/misc"
                    os.makedirs(debug_dir, exist_ok=True)

                    safe_records = []

                    for record in df_out.to_dict(orient="records"):

                        clean_record = {
                            k: self.clean_value(v)
                            for k, v in record.items()
                        }

                        safe_records.append(clean_record)

                    with open(f"{debug_dir}/{json_filename}", "w", encoding="utf-8") as f:
                        json.dump(safe_records, f, ensure_ascii=False, indent=2)

                    print("✅ FULL DATAFRAME JSON exported")

                except Exception as e:
                    print(f"⚠ JSON export failed: {e}")

            return DataFrame(df_out)

        except Exception as e:
            print(f"⚠ Final formatter failed safely: {e}")
            return DataFrame(pd.DataFrame())

