logger = logging.getLogger(__name__)


class MdFileRead(Component):
    """
    Reads a markdown/text file per row and appends its content as a new
    `text` column. Designed for the markdown ingestion flow: it takes the
    upstream DataFrame (e.g. DataFrameOperations-M0GaP-MD), reads the file
    referenced by a path column, and returns the same rows + `text`.

    File reading follows the PDFPlumberToDataFrame pattern (iterate rows,
    read `file_path`, skip missing) but reads UTF-8 text instead of a PDF.

    Czech encoding: files are read as bytes and decoded UTF-8-first, with a
    chardet-based fallback for legacy Czech encodings (Windows-1250 /
    ISO-8859-2), and a final errors='replace' so it never crashes.
    """

    display_name = "Read Markdown File"
    description = (
        "Reads the file at the given path column for each row and adds its "
        "content as a new 'text' column. UTF-8 first, with Czech legacy "
        "fallback (cp1250 / ISO-8859-2) via chardet."
    )

    inputs = [
        DataFrameInput(
            name="dataframe",
            display_name="Input DataFrame",
            info="Output of the upstream component (e.g. DataFrameOperations-M0GaP-MD).",
        ),
        StrInput(
            name="path_column",
            display_name="Path column",
            value="file_path",
            info="Column holding the file path to read. For the markdown "
                 "handoff point this at the .md file (e.g. markdown_file_path).",
        ),
        StrInput(
            name="output_column",
            display_name="Output column",
            value="text",
            advanced=True,
        ),
    ]

    outputs = [
        Output(
            name="result",
            display_name="DataFrame + text",
            method="process",
            type=DataFrame,
        )
    ]

    def process(self) -> DataFrame:
        df = self.dataframe
        if not isinstance(df, pd.DataFrame) or df.empty:
            logger.warning("[MD READ] empty/invalid input")
            return DataFrame(df if isinstance(df, pd.DataFrame) else pd.DataFrame())

        col = (self.path_column or "file_path").strip() or "file_path"
        out_col = (self.output_column or "text").strip() or "text"

        if col not in df.columns:
            logger.error(f"[MD READ] path column '{col}' not in DataFrame "
                         f"(have: {list(df.columns)})")

        texts = []
        ok = 0
        for _, row in df.iterrows():
            path = row.get(col) if col in df.columns else None
            if isinstance(path, str) and path and os.path.exists(path):
                try:
                    texts.append(self._read_text(path))
                    ok += 1
                except Exception as e:
                    logger.error(f"[MD READ] failed reading {path}: {e}")
                    texts.append(None)
            else:
                logger.warning(f"[MD READ] missing/invalid path in '{col}': {path!r}")
                texts.append(None)

        result = df.copy()
        result[out_col] = texts
        logger.info(f"[MD READ] read {ok}/{len(texts)} files into '{out_col}'")
        return DataFrame(result)

    # ── Czech-aware text reader ──────────────────────────────
    def _read_text(self, path: str) -> str:
        with open(path, "rb") as f:
            raw = f.read()

        # 1) UTF-8 (our MarkdownFileSaver writes UTF-8); handle BOM
        for enc in ("utf-8-sig", "utf-8"):
            try:
                return raw.decode(enc)
            except UnicodeDecodeError:
                pass

        # 2) detect legacy Czech encodings (Windows-1250 / ISO-8859-2)
        try:
            import chardet
            enc = (chardet.detect(raw).get("encoding") or "").strip()
            if enc:
                try:
                    return raw.decode(enc)
                except (UnicodeDecodeError, LookupError):
                    pass
        except Exception:
            pass

        # 3) explicit Czech legacy fallbacks
        for enc in ("cp1250", "iso-8859-2"):
            try:
                return raw.decode(enc)
            except UnicodeDecodeError:
                pass

        # 4) never crash — replace undecodable bytes
        return raw.decode("utf-8", errors="replace")

