import pandas as pd


class JoinDocumentContext(Component):
    display_name = "Join Document Context onto Chunks"
    description = (
        "Left-joins per-file document context (document_header, "
        "school_grade_document, document_type, school_subject) onto every chunk "
        "row by file_uuid. The chunk enrichment and the chunk/keyword inserts "
        "then carry document-level metadata directly — no post-insert UPDATE. "
        "Context comes from the document-metadata insert output (input B); chunk "
        "rows come from the chunk branch (input A)."
    )

    inputs = [
        DataFrameInput(name="chunk_df", display_name="Chunk Rows (branch A)"),
        DataFrameInput(name="context_df", display_name="Document Context (branch B)"),
    ]

    outputs = [
        Output(name="result", display_name="Chunks + Context", method="process", type=DataFrame),
    ]

    @staticmethod
    def _as_int(v):
        try:
            if v is None or (isinstance(v, float) and pd.isna(v)) or str(v).strip() == "":
                return None
            return int(v)
        except Exception:
            return None

    @staticmethod
    def _as_str(v):
        if v is None or (isinstance(v, float) and pd.isna(v)) or str(v).strip() in ("", "nan", "None"):
            return None
        return str(v)

    def process(self) -> DataFrame:
        chunks = self.chunk_df
        ctx = self.context_df
        if not isinstance(chunks, pd.DataFrame) or chunks.empty:
            return DataFrame(chunks if isinstance(chunks, pd.DataFrame) else pd.DataFrame())

        # per-file context from the metadata-insert output row(s); grade is the
        # resolved id, user-entered winning over the LLM one (COALESCE order).
        lookup = {}
        if isinstance(ctx, pd.DataFrame) and not ctx.empty:
            for _, r in ctx.iterrows():
                fu = self._as_str(r.get("file_uuid"))
                if not fu:
                    continue
                lookup[fu] = {
                    "document_header": self._as_str(r.get("document_header")),
                    # doc-level grade SET as ids (item 1) + the document's binding and
                    # its grade whitelist for the chunk trim (item 3) — carried as
                    # JSON strings the chunk/keyword inserts json.loads.
                    "school_grade_document_ids": r.get("school_grade_document_ids"),
                    "document_binding_id": self._as_int(r.get("document_binding_id")),
                    "binding_grade_ids": r.get("binding_grade_ids"),
                    "document_type": self._as_str(r.get("document_type")),
                    "school_subject": self._as_str(r.get("school_subject")),
                    "document_domain_id": r.get("document_domain_id"),
                    "school_subject_document": self._as_int(r.get("school_subject_document")),
                }

        out = chunks.copy()
        if "file_uuid" not in out.columns:
            return DataFrame(out)

        def pick(fu, key):
            return lookup.get(self._as_str(fu), {}).get(key)

        out["document_header"] = out["file_uuid"].map(lambda x: pick(x, "document_header"))
        out["school_grade_document_ids"] = out["file_uuid"].map(lambda x: pick(x, "school_grade_document_ids"))
        out["document_binding_id"] = out["file_uuid"].map(lambda x: pick(x, "document_binding_id"))
        out["binding_grade_ids"] = out["file_uuid"].map(lambda x: pick(x, "binding_grade_ids"))
        out["document_type_ctx"] = out["file_uuid"].map(lambda x: pick(x, "document_type"))
        out["school_subject_ctx"] = out["file_uuid"].map(lambda x: pick(x, "school_subject"))
        out["document_domain_id"] = out["file_uuid"].map(lambda x: pick(x, "document_domain_id"))
        out["school_subject_document"] = out["file_uuid"].map(lambda x: pick(x, "school_subject_document"))
        return DataFrame(out)
